def blocks(g,c):
    # find rectangles of color c in grid g
    h,w=len(g),len(g[0]); seen=set(); res=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==c and (i,j) not in seen:
                stack=[(i,j)]; comp=set()
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen or g[y][x]!=c: continue
                    seen.add((y,x)); comp.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
