def cc(g,val,bg):
    # find components of value 'val' treating background 'bg' as wall
    n,m=len(g),len(g[0]); seen=[[0]*m for _ in range(n)]; res=[]
    for i in range(n):
        for j in range(m):
            if g[i][j]==val and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=1; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<n and 0<=y<m and not seen[x][y] and g[x][y]==val:
                            seen[x][y]=1; q.append((x,y))
                rs=[p_[0] for p_ in cells]; cs=[p_[1] for p_ in cells]
                res.append(dict(col=val,top=min(rs),bot=max(rs),left=min(cs),right=max(cs)))
    return res
